--
-- Table structure for table `order_sale`
--

DROP TABLE IF EXISTS `order_sale`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_sale` (
  `id` bigint unsigned NOT NULL,
  `openid` bigint unsigned NOT NULL COMMENT '微信唯一id',
  `sale_date` datetime NOT NULL COMMENT '销售日期',
  `sale_quantity` int unsigned NOT NULL COMMENT '销售数量',
  `shop_id` bigint unsigned NOT NULL COMMENT '所属店铺',
  `sale_amount` decimal(18,4) NOT NULL COMMENT '销售金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `create_by` bigint unsigned NOT NULL,
  `update_by` bigint unsigned NOT NULL,
  `deleted` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

